<?php
declare(strict_types=1);
namespace Sinaesta\Assessment\Http;
use Sinaesta\Assessment\Application\AssessmentService;use Sinaesta\Shared\Http\Request;use Sinaesta\Shared\Http\Response;
final readonly class AssessmentController{public function __construct(private AssessmentService$service){}private function user(Request$r):int{return(int)$r->attribute('user')['internal_id'];}public function config(Request$r):Response{return Response::success('Konfigurasi latihan.',$this->service->config());}public function startPractice(Request$r):Response{return Response::success('Attempt berhasil dimulai.',$this->service->startPractice($this->user($r),$r->json()),201);}public function tryouts(Request$r):Response{return Response::success('Daftar tryout.',$this->service->tryouts());}public function tryout(Request$r):Response{return Response::success('Detail tryout.',$this->service->tryout((string)$r->attribute('tryoutId')));}public function startTryout(Request$r):Response{return Response::success('Tryout berhasil dimulai.',$this->service->startTryout($this->user($r),(string)$r->attribute('tryoutId')),201);}public function attempt(Request$r):Response{return Response::success('Attempt.',$this->service->view((string)$r->attribute('attemptId'),$this->user($r)));}public function answer(Request$r):Response{return Response::success('Jawaban tersimpan.',$this->service->save((string)$r->attribute('attemptId'),(string)$r->attribute('questionId'),$this->user($r),$r->json()));}public function addFlag(Request$r):Response{$this->service->flag((string)$r->attribute('attemptId'),(string)$r->attribute('questionId'),$this->user($r),true);return Response::success('Soal ditandai.');}public function removeFlag(Request$r):Response{$this->service->flag((string)$r->attribute('attemptId'),(string)$r->attribute('questionId'),$this->user($r),false);return Response::success('Tanda dihapus.');}public function submit(Request$r):Response{return Response::success('Attempt berhasil disubmit.',$this->service->submit((string)$r->attribute('attemptId'),$this->user($r)));}public function result(Request$r):Response{return Response::success('Hasil attempt.',$this->service->result((string)$r->attribute('attemptId'),$this->user($r)));}public function review(Request$r):Response{return Response::success('Pembahasan attempt.',$this->service->review((string)$r->attribute('attemptId'),$this->user($r)));}public function mine(Request$r):Response{return Response::success('Riwayat attempt.',$this->service->attempts($this->user($r)));}public function analytics(Request$r):Response{return Response::success('Analitik pengguna.',$this->service->analytics($this->user($r)));}public function wrong(Request$r):Response{return Response::success('Soal salah.',$this->service->wrong($this->user($r)));}public function bookmarks(Request$r):Response{return Response::success('Bookmark.',$this->service->bookmarks($this->user($r)));}}
